package com.groundorder;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class GroundOrderTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GroundOrderPlugin.class);
		RuneLite.main(args);
	}
}

package com.groundorder;

import com.google.inject.Provides;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ItemLayer;
import net.runelite.api.Model;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Texture;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.events.ClientTick;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Wraps the client's DrawCallbacks to selectively suppress the draw calls the engine makes for
 * the bottom/middle/top renderables of a tile's ItemLayer (the "pile" of up to 3 ground items
 * shown on a tile), based on each item's Grand Exchange or High Alchemy value.
 */
@Slf4j
@PluginDescriptor(
	name = "Ground Focus Items",
	description = "Jagex sends your client 3 item meshes per stack.",
	tags = {"ground", "items", "value", "hide", "sort", "scale"}
)
public class GroundOrderPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private GroundItemValueService valueService;

	private DrawCallbacks original;

	@Provides
	GroundOrderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GroundOrderConfig.class);
	}

	@Override
	protected void startUp()
	{
		clientThread.invoke(this::ensureDrawCallbacksInstalled);
	}

	/**
	 * The real renderer (GpuPlugin) may not have installed its DrawCallbacks yet when this
	 * plugin's startUp() runs, and it may also install/replace its callbacks again after us
	 * (e.g. if it's toggled or starts later). Rewrapping on every ClientTick makes this
	 * self-healing instead of racing plugin startup order. ClientTick (unlike GameTick) fires
	 * every client frame regardless of login state, so this also recovers while still sitting at
	 * the login screen instead of only once logged into a world. Runs on the client thread
	 * already since it's a @Subscribe handler invoked from Callbacks.post().
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		ensureDrawCallbacksInstalled();
	}

	private void ensureDrawCallbacksInstalled()
	{
		DrawCallbacks current = client.getDrawCallbacks();
		if (current == null || current instanceof ItemLayerInspectingDrawCallbacks)
		{
			return;
		}

		original = current;
		client.setDrawCallbacks(new ItemLayerInspectingDrawCallbacks(original));
		log.info("[GroundOrder] installed DrawCallbacks proxy wrapping {}", original.getClass());
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(() ->
		{
			if (client.getDrawCallbacks() instanceof ItemLayerInspectingDrawCallbacks)
			{
				client.setDrawCallbacks(original);
			}
			original = null;
		});
	}

	private final class ItemLayerInspectingDrawCallbacks implements DrawCallbacks
	{
		private final DrawCallbacks delegate;

		private ItemLayerInspectingDrawCallbacks(DrawCallbacks delegate)
		{
			this.delegate = delegate;
		}

		@Override
		public void draw(Projection projection, Scene scene, Renderable renderable, int orientation, int x, int y, int z, long hash)
		{
			delegate.draw(projection, scene, renderable, orientation, x, y, z, hash);
		}

		@Override
		public void drawScenePaint(Scene scene, SceneTilePaint paint, int plane, int tileX, int tileZ)
		{
			delegate.drawScenePaint(scene, paint, plane, tileX, tileZ);
		}

		@Override
		public void drawSceneTileModel(Scene scene, SceneTileModel model, int tileX, int tileZ)
		{
			delegate.drawSceneTileModel(scene, model, tileX, tileZ);
		}

		@Override
		public void draw(int overlayColor)
		{
			delegate.draw(overlayColor);
		}

		@Override
		public void drawScene(double cameraX, double cameraY, double cameraZ, double cameraPitch, double cameraYaw, int plane)
		{
			delegate.drawScene(cameraX, cameraY, cameraZ, cameraPitch, cameraYaw, plane);
		}

		@Override
		public void postDrawScene()
		{
			delegate.postDrawScene();
		}

		@Override
		public void animate(Texture texture, int diff)
		{
			delegate.animate(texture, diff);
		}

		@Override
		public void loadScene(Scene scene)
		{
			delegate.loadScene(scene);
		}

		@Override
		public void swapScene(Scene scene)
		{
			delegate.swapScene(scene);
		}

		@Override
		public boolean tileInFrustum(Scene scene, float pitchSin, float pitchCos, float yawSin, float yawCos, int cameraX, int cameraY, int cameraZ, int plane, int msx, int msy)
		{
			return delegate.tileInFrustum(scene, pitchSin, pitchCos, yawSin, yawCos, cameraX, cameraY, cameraZ, plane, msx, msy);
		}

		@Override
		public boolean zoneInFrustum(int zoneX, int zoneZ, int maxY, int minY)
		{
			return delegate.zoneInFrustum(zoneX, zoneZ, maxY, minY);
		}

		@Override
		public void loadScene(WorldView worldView, Scene scene)
		{
			delegate.loadScene(worldView, scene);
		}

		@Override
		public void despawnWorldView(WorldView worldView)
		{
			delegate.despawnWorldView(worldView);
		}

		@Override
		public void preSceneDraw(Scene scene, Projection entityProjection, float cameraX, float cameraY, float cameraZ, float cameraPitch, float cameraYaw, int minLevel, int level, int maxLevel, Set<Integer> hideRoofIds)
		{
			delegate.preSceneDraw(scene, entityProjection, cameraX, cameraY, cameraZ, cameraPitch, cameraYaw, minLevel, level, maxLevel, hideRoofIds);
		}

		@Override
		public void preSceneDraw(Scene scene, float cameraX, float cameraY, float cameraZ, float cameraPitch, float cameraYaw, int minLevel, int level, int maxLevel, Set<Integer> hideRoofIds)
		{
			delegate.preSceneDraw(scene, cameraX, cameraY, cameraZ, cameraPitch, cameraYaw, minLevel, level, maxLevel, hideRoofIds);
		}

		@Override
		public void postSceneDraw(Scene scene)
		{
			delegate.postSceneDraw(scene);
		}

		@Override
		public void drawPass(Projection entityProjection, Scene scene, int pass)
		{
			delegate.drawPass(entityProjection, scene, pass);
		}

		@Override
		public void drawZoneOpaque(Projection entityProjection, Scene scene, int zx, int zz)
		{
			delegate.drawZoneOpaque(entityProjection, scene, zx, zz);
		}

		@Override
		public void drawZoneAlpha(Projection entityProjection, Scene scene, int level, int zx, int zz)
		{
			delegate.drawZoneAlpha(entityProjection, scene, level, zx, zz);
		}

		@Override
		public void drawDynamic(Projection worldProjection, Scene scene, TileObject tileObject, Renderable r, Model m, int orient, int x, int y, int z)
		{
			if (tileObject instanceof ItemLayer)
			{
				ItemLayer layer = (ItemLayer) tileObject;
				valueService.drawSlot(layer, r, m, (rr, mm) -> delegate.drawDynamic(worldProjection, scene, tileObject, rr, mm, orient, x, y, z));
				return;
			}
			delegate.drawDynamic(worldProjection, scene, tileObject, r, m, orient, x, y, z);
		}

		@Override
		public void drawDynamic(int renderThreadId, Projection worldProjection, Scene scene, TileObject tileObject, Renderable r, Model m, int orient, int x, int y, int z)
		{
			if (tileObject instanceof ItemLayer)
			{
				ItemLayer layer = (ItemLayer) tileObject;
				valueService.drawSlot(layer, r, m, (rr, mm) -> delegate.drawDynamic(renderThreadId, worldProjection, scene, tileObject, rr, mm, orient, x, y, z));
				return;
			}
			delegate.drawDynamic(renderThreadId, worldProjection, scene, tileObject, r, m, orient, x, y, z);
		}

		@Override
		public void drawTemp(Projection worldProjection, Scene scene, GameObject gameObject, Model m, int orient, int x, int y, int z)
		{
			delegate.drawTemp(worldProjection, scene, gameObject, m, orient, x, y, z);
		}

		@Override
		public void invalidateZone(Scene scene, int zx, int zz)
		{
			delegate.invalidateZone(scene, zx, zz);
		}
	}
}

package com.groundorder;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("groundorder")
public interface GroundOrderConfig extends Config
{
	enum PriceSource
	{
		GRAND_EXCHANGE,
		HIGH_ALCHEMY
	}

	@ConfigSection(
		name = "Sorting",
		description = "Ranks the pile's items by value into item #1 (most valuable), #2, and #3. Filtering, "
			+ "scaling, and the focus item below all act on these ranks.",
		position = 0
	)
	String sortingSection = "sortingSection";

	@ConfigItem(
		keyName = "priceSource",
		name = "Value type",
		description = "Whether ranking judges an item's value by its Grand Exchange price or its High Alchemy value",
		section = sortingSection,
		position = 0
	)
	default PriceSource priceSource()
	{
		return PriceSource.GRAND_EXCHANGE;
	}

	@ConfigSection(
		name = "Filtering and scaling",
		description = "Show/hide and resize each ranked item individually. Item 1 is always the most valuable item "
			+ "in the pile, item 2 the second most valuable, item 3 the least valuable, using the value type set "
			+ "above.",
		position = 1
	)
	String filterSection = "filterSection";

	@ConfigItem(
		keyName = "showItem1",
		name = "Show item 1",
		description = "Shows item #1, the most valuable item in the pile",
		section = filterSection,
		position = 0
	)
	default boolean showItem1()
	{
		return true;
	}

	@Range(min = 10, max = 1000)
	@ConfigItem(
		keyName = "item1Scale",
		name = "Item 1 size (%)",
		description = "Renders item #1 at this percentage of its normal mesh size. Min 10%, max 1000%.",
		section = filterSection,
		position = 1
	)
	default int item1Scale()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "showItem2",
		name = "Show item 2",
		description = "Shows item #2, the second most valuable item in the pile",
		section = filterSection,
		position = 2
	)
	default boolean showItem2()
	{
		return true;
	}

	@Range(min = 10, max = 1000)
	@ConfigItem(
		keyName = "item2Scale",
		name = "Item 2 size (%)",
		description = "Renders item #2 at this percentage of its normal mesh size. Min 10%, max 1000%.",
		section = filterSection,
		position = 3
	)
	default int item2Scale()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "showItem3",
		name = "Show item 3",
		description = "Shows item #3, the least valuable item in the pile",
		section = filterSection,
		position = 4
	)
	default boolean showItem3()
	{
		return true;
	}

	@Range(min = 10, max = 1000)
	@ConfigItem(
		keyName = "item3Scale",
		name = "Item 3 size (%)",
		description = "Renders item #3 at this percentage of its normal mesh size. Min 10%, max 1000%.",
		section = filterSection,
		position = 5
	)
	default int item3Scale()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "alwaysHideItems",
		name = "Items to always hide completely",
		description = "Comma-separated item names to always hide, regardless of rank or value (e.g. Bones, Ashes, Feather)",
		section = filterSection,
		position = 6
	)
	default String alwaysHideItems()
	{
		return "";
	}

	@ConfigItem(
		keyName = "hideBelowValue",
		name = "Hide items below value",
		description = "Hides any item worth less than the threshold below, regardless of rank",
		section = filterSection,
		position = 7
	)
	default boolean hideBelowValue()
	{
		return false;
	}

	@ConfigItem(
		keyName = "minValueThreshold",
		name = "Minimum value (gp)",
		description = "Items worth less than this are hidden",
		section = filterSection,
		position = 8
	)
	default int minValueThreshold()
	{
		return 1000;
	}

	@ConfigSection(
		name = "Focus item",
		description = "Defines a value-based or name-based 'focus item' in the pile, and can render it alone with "
			+ "everything else in that pile hidden.",
		position = 2
	)
	String focusSection = "focusSection";

	@ConfigItem(
		keyName = "focusItemValue",
		name = "Focus item threshold",
		description = "An item worth at least this much (using the value type above) qualifies as the pile's focus item",
		section = focusSection,
		position = 0
	)
	default int focusItemValue()
	{
		return 100_000;
	}

	@ConfigItem(
		keyName = "renderFocusItemInIsolation",
		name = "Isolate focus item",
		description = "When item #1 (the most valuable item) qualifies as a focus item, hides every other item in that pile",
		section = focusSection,
		position = 1
	)
	default boolean renderFocusItemInIsolation()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showAloneItems",
		name = "Focus items",
		description = "Comma-separated item names that are always treated as the pile's focus item and rendered "
			+ "alone, with everything else hidden (e.g. Clue scroll (elite))",
		section = focusSection,
		position = 2
	)
	default String showAloneItems()
	{
		return "";
	}

	@Range(min = 10, max = 1000)
	@ConfigItem(
		keyName = "focusItemScale",
		name = "Focus item scaling (%)",
		description = "Renders the focus item at this percentage of its normal mesh size when isolated. Min 10%, max 1000%.",
		section = focusSection,
		position = 3
	)
	default int focusItemScale()
	{
		return 150;
	}
}

package com.groundorder;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.Set;
import java.util.function.BiConsumer;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemLayer;
import net.runelite.api.Model;
import net.runelite.api.Renderable;
import net.runelite.api.TileItem;
import net.runelite.client.game.ItemManager;

/**
 * Ranks a ground item pile's up-to-3 slots by value, then decides -- per draw call -- whether the
 * item currently being drawn should be shown at all (per-rank checkboxes, value/name filters, and
 * the focus item) and at what scale. Shared by the mesh DrawCallbacks hook so filtering, scaling
 * and the focus item all agree on the same ranking.
 */
class GroundItemValueService
{
	private static final long UNKNOWN_VALUE = -1L;

	// Fixed-point scale unity used by Model/Mesh.scale(x, y, z): 128 means "unscaled".
	private static final int SCALE_UNITY = 128;

	private final Client client;
	private final GroundOrderConfig config;
	private final ItemManager itemManager;

	// Cached parses of the comma-separated name-list config strings, memoized against the raw
	// string so repeated per-frame calls don't re-split it unless the user actually changed it.
	private String lastAlwaysHideRaw;
	private Set<String> alwaysHideNames = Collections.emptySet();
	private String lastShowAloneRaw;
	private Set<String> showAloneNames = Collections.emptySet();

	@Inject
	private GroundItemValueService(Client client, GroundOrderConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;
	}

	/** One pile slot: the renderable occupying it, its value, and its value rank (1 = most valuable). */
	private static final class Slot
	{
		final Renderable renderable;
		final long value;
		int rank;

		Slot(Renderable renderable, long value)
		{
			this.renderable = renderable;
			this.value = value;
		}
	}

	/**
	 * Called once per pile slot draw call. Ranks the pile, applies this slot's rank-based show/hide
	 * and scale settings plus the value thresholds, and invokes {@code drawer} with the resulting
	 * model -- or not at all, if it should be hidden. The Model instance is the engine's
	 * shared/cached mesh for an item -- also used for its inventory icon, minimap dot, etc. -- so
	 * any scale is always undone before returning, regardless of how drawer behaves.
	 */
	void drawSlot(ItemLayer layer, Renderable r, Model model, BiConsumer<Renderable, Model> drawer)
	{
		List<Slot> slots = buildSlots(layer);

		Slot mySlot = null;
		for (Slot s : slots)
		{
			if (s.renderable == r)
			{
				mySlot = s;
				break;
			}
		}
		if (mySlot == null)
		{
			drawer.accept(r, model);
			return;
		}

		boolean focus = isFocus(mySlot);
		if (!isShown(mySlot, slots, focus))
		{
			return;
		}

		int percent = Math.max(10, Math.min(1000, focus ? config.focusItemScale() : scaleForRank(mySlot.rank)));
		if (percent == 100)
		{
			drawer.accept(r, model);
			return;
		}

		// scale(...) mutates the mesh's live, persistent vertex arrays in place. Undoing it with a
		// second inverse scale() call left a small fixed-point rounding error every round trip
		// (e.g. factor=136 inverts to 120, but 136*120=16320 != 128*128=16384), which compounded
		// on every draw call and visibly shrank the item over time. Snapshotting and restoring the
		// exact original floats avoids that rounding entirely.
		int factor = Math.round(SCALE_UNITY * percent / 100f);
		float[] xs = model.getVerticesX();
		float[] ys = model.getVerticesY();
		float[] zs = model.getVerticesZ();
		float[] origXs = xs.clone();
		float[] origYs = ys.clone();
		float[] origZs = zs.clone();

		model.scale(factor, factor, factor);
		try
		{
			drawer.accept(r, model);
		}
		finally
		{
			System.arraycopy(origXs, 0, xs, 0, xs.length);
			System.arraycopy(origYs, 0, ys, 0, ys.length);
			System.arraycopy(origZs, 0, zs, 0, zs.length);
		}
	}

	/**
	 * Builds the pile's present slots with their values, then ranks them by value descending (ties
	 * keep bottom-before-middle-before-top order) to assign rank 1 (most valuable) through rank N.
	 */
	private List<Slot> buildSlots(ItemLayer layer)
	{
		List<Slot> slots = new ArrayList<>(3);
		Renderable bottom = layer.getBottom();
		Renderable middle = layer.getMiddle();
		Renderable top = layer.getTop();
		if (bottom != null)
		{
			slots.add(new Slot(bottom, itemValue(bottom)));
		}
		if (middle != null)
		{
			slots.add(new Slot(middle, itemValue(middle)));
		}
		if (top != null)
		{
			slots.add(new Slot(top, itemValue(top)));
		}

		List<Slot> byValue = new ArrayList<>(slots);
		byValue.sort((a, b) -> Long.compare(b.value, a.value));
		for (int i = 0; i < byValue.size(); i++)
		{
			byValue.get(i).rank = i + 1;
		}
		return slots;
	}

	/**
	 * A slot is the pile's focus item if its name is in the "always defined as focus item" list, or
	 * if it's item #1 (most valuable) worth at least the configured focus value and isolation is
	 * enabled.
	 */
	private boolean isFocus(Slot slot)
	{
		if (matchesName(itemName(slot.renderable), showAloneNames()))
		{
			return true;
		}
		return config.renderFocusItemInIsolation() && slot.rank == 1 && slot.value >= config.focusItemValue();
	}

	private boolean anyFocus(List<Slot> slots)
	{
		for (Slot s : slots)
		{
			if (isFocus(s))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isShown(Slot slot, List<Slot> slots, boolean focus)
	{
		if (matchesName(itemName(slot.renderable), alwaysHideNames()))
		{
			return false;
		}

		if (anyFocus(slots))
		{
			return focus;
		}

		switch (slot.rank)
		{
			case 1:
				if (!config.showItem1())
				{
					return false;
				}
				break;
			case 2:
				if (!config.showItem2())
				{
					return false;
				}
				break;
			case 3:
				if (!config.showItem3())
				{
					return false;
				}
				break;
			default:
				break;
		}

		if (config.hideBelowValue() && slot.value < config.minValueThreshold())
		{
			return false;
		}

		return true;
	}

	private int scaleForRank(int rank)
	{
		switch (rank)
		{
			case 1:
				return config.item1Scale();
			case 2:
				return config.item2Scale();
			case 3:
				return config.item3Scale();
			default:
				return 100;
		}
	}

	/**
	 * Resolves a pile slot's item name via the same canonicalized id used for pricing, or null if
	 * the slot is empty or isn't a TileItem.
	 */
	private String itemName(Renderable renderable)
	{
		if (!(renderable instanceof TileItem))
		{
			return null;
		}

		TileItem tileItem = (TileItem) renderable;
		int canonicalId = itemManager.canonicalize(tileItem.getId());
		ItemComposition comp = client.getItemDefinition(canonicalId);
		return comp == null ? null : comp.getName();
	}

	private boolean matchesName(String name, Set<String> names)
	{
		return name != null && !names.isEmpty() && names.contains(name.toLowerCase(Locale.ROOT));
	}

	private Set<String> alwaysHideNames()
	{
		String raw = config.alwaysHideItems();
		if (!Objects.equals(raw, lastAlwaysHideRaw))
		{
			lastAlwaysHideRaw = raw;
			alwaysHideNames = parseNames(raw);
		}
		return alwaysHideNames;
	}

	private Set<String> showAloneNames()
	{
		String raw = config.showAloneItems();
		if (!Objects.equals(raw, lastShowAloneRaw))
		{
			lastShowAloneRaw = raw;
			showAloneNames = parseNames(raw);
		}
		return showAloneNames;
	}

	private static Set<String> parseNames(String raw)
	{
		if (raw == null || raw.isBlank())
		{
			return Collections.emptySet();
		}

		Set<String> names = new HashSet<>();
		for (String token : raw.split(","))
		{
			String trimmed = token.trim();
			if (!trimmed.isEmpty())
			{
				names.add(trimmed.toLowerCase(Locale.ROOT));
			}
		}
		return names;
	}

	/**
	 * Resolves a pile slot's total value (unit price * quantity) using the configured price
	 * source, or UNKNOWN_VALUE if the slot is empty or isn't a TileItem.
	 */
	private long itemValue(Renderable renderable)
	{
		if (!(renderable instanceof TileItem))
		{
			return UNKNOWN_VALUE;
		}

		TileItem tileItem = (TileItem) renderable;
		int canonicalId = itemManager.canonicalize(tileItem.getId());

		int unitPrice;
		if (config.priceSource() == GroundOrderConfig.PriceSource.HIGH_ALCHEMY)
		{
			ItemComposition comp = client.getItemDefinition(canonicalId);
			unitPrice = comp == null ? 0 : comp.getHaPrice();
		}
		else
		{
			unitPrice = itemManager.getItemPrice(canonicalId);
		}

		return (long) unitPrice * Math.max(tileItem.getQuantity(), 1);
	}
}
